using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B1StaffData {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B1_StaffDataRevision/";static string O=>R+"/Docs/Review/2026-11-11_B1_StaffData/";const string E="Assets/Afrer_Seconds/05.Model/Environment/B1/";const string P="Assets/Afrer_Seconds/05.Model/Props/B1/";
 static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B1_Circular.unity"))throw new Exception("Saved edit B1 required");return s;}
 static Material Display(string name,string file){string path=E+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/B1M_Display_01.mat")){name=name};AssetDatabase.CreateAsset(m,path);}var t=AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/"+file);if(!t)throw new Exception(file);m.SetTexture("_BaseMap",t);m.SetTexture("_EmissionMap",t);m.SetColor("_EmissionColor",Color.white*.5f);m.EnableKeyword("_EMISSION");EditorUtility.SetDirty(m);return m;}
 public static object Apply(){var s=Check();if(File.Exists(O+"applied.json"))throw new Exception("Already applied; scoped follow-up only");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;var changes=JObject.Parse(File.ReadAllText(H+"changes.json"));var old=JObject.Parse(File.ReadAllText(H+"before_layout.json"));var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));
  var removed=new HashSet<string>(changes["remove"].Select(p=>(string)p["name"]));var retained=old["placements"].Where(p=>!removed.Contains((string)p["name"])).Select(p=>root.Find("B1_"+(string)p["room"]+"_Sector/Equipment/"+(string)p["name"])).ToArray();if(retained.Any(t=>!t))throw new Exception("Retained placement missing");var state=retained.ToDictionary(t=>t,t=>new[]{t.localPosition,t.localEulerAngles,t.localScale});
  var templates=changes["add"].Select(p=>new{room=(string)p["templateRoom"],name=(string)p["template"]}).Distinct().ToDictionary(p=>p.name,p=>root.Find("B1_"+p.room+"_Sector/Equipment/"+p.name));if(templates.Any(q=>!q.Value))throw new Exception("Template missing");
  Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("B1 staff/data role correction");
  foreach(var p in changes["remove"]){var t=root.Find("B1_"+(string)p["room"]+"_Sector/Equipment/"+(string)p["name"]);if(!t)throw new Exception("Missing removal "+p["name"]);Undo.DestroyObjectImmediate(t.gameObject);}
  int added=0;foreach(var p in changes["add"]){var eq=root.Find("B1_"+(string)p["room"]+"_Sector/Equipment");var g=UnityEngine.Object.Instantiate(templates[(string)p["template"]].gameObject,eq);Undo.RegisterCreatedObjectUndo(g,"B1 data furniture");g.name=(string)p["name"];g.transform.localPosition=V(p["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);foreach(var t in g.GetComponentsInChildren<Transform>(true))GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.OccludeeStatic);added++;}
  var data=Display("BL_DataReview","BL_DataReview.png");var security=Display("BL_AccessSecurity","BL_AccessSecurity.png");int screens=0;
  foreach(var room in new[]{"C01","C02","C03","C05","W01","E01","E02","N01","S01"})foreach(var rr in root.Find("B1_"+room+"_Sector/Equipment").GetComponentsInChildren<Renderer>(true)){var ms=rr.sharedMaterials;bool dirty=false;for(int i=0;i<ms.Length;i++){var m=ms[i];if(!m||!m.name.Contains("Display")||m.name=="B1M_Display_01")continue;ms[i]=room=="E01"?security:data;dirty=true;screens++;}if(dirty){Undo.RecordObject(rr,"B1 purpose screens");rr.sharedMaterials=ms;}}
  foreach(var room in new[]{"C01","C02","C05","N01"})foreach(var l in root.Find("B1_"+room+"_Sector/Lighting").GetComponentsInChildren<Light>(true)){Undo.RecordObject(l,"B1 work light");l.color=new Color(1,.94f,.84f);}
  foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
  var errors=state.Where(q=>(q.Key.localPosition-q.Value[0]).sqrMagnitude>.00000001f||(q.Key.localEulerAngles-q.Value[1]).sqrMagnitude>.000001f||(q.Key.localScale-q.Value[2]).sqrMagnitude>.00000001f).Select(q=>q.Key.name).ToArray();if(errors.Length>0)throw new Exception("Retained placement changed "+string.Join(",",errors));
  Physics.SyncTransforms();Undo.CollapseUndoOperations(undo);EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);
  File.WriteAllText(R+"/SourceAssets/B1_FullFloor/layout.json",plan.ToString());File.WriteAllText(R+"/Docs/도면/Decision/원형공동/B1_제작현황/as_built_layout.json",plan.ToString());
  var result=new{removed=removed.Count,added,total=plan["placements"].Count(),screens,retainedPlacements=retained.Length,retainedTransformErrors=errors,newMeshes=0,geometry="Existing cleaned scene templates cloned; architecture and colliders retained except replaced furniture."};File.WriteAllText(O+"applied.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Conference(){var s=Check();if(File.Exists(O+"conference_applied.json"))throw new Exception("Already applied");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var models=JObject.Parse(File.ReadAllText(H+"models_props.json"));var screen=Display("BL_Presentation","BL_Presentation.png");
  foreach(var kv in models){var q=kv.Value;var mi=(ModelImporter)AssetImporter.GetAtPath((string)q["asset"]);mi.importAnimation=false;mi.animationType=ModelImporterAnimationType.None;mi.isReadable=false;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;mi.materialLocation=ModelImporterMaterialLocation.InPrefab;foreach(string name in q["materials"].Select(v=>(string)v).Distinct()){var m=name=="B1M_Display_01"?screen:AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/"+name+".mat");if(!m)throw new Exception("Material "+name);mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),name),m);}mi.SaveAndReimport();}
  var change=JObject.Parse(File.ReadAllText(H+"conference_plan.json"));var root=GameObject.Find("B1_ResearchAndStaffFloor").transform;var eq=root.Find("B1_C05_Sector/Equipment");var chair=root.Find("B1_W01_Sector/Equipment/"+(string)change["template"]);if(!chair)throw new Exception("Chair template");Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("B1 eight-seat conference room");foreach(string name in change["remove"].Select(x=>(string)x)){var t=eq.Find(name);if(!t)throw new Exception(name);Undo.DestroyObjectImmediate(t.gameObject);}
  foreach(var q in change["add"]){bool seat=(string)q["model"]=="SF_TaskChair";var g=seat?UnityEngine.Object.Instantiate(chair.gameObject,eq):(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((string)q["asset"]),eq);Undo.RegisterCreatedObjectUndo(g,"Conference furniture");g.name=(string)q["name"];g.transform.localPosition=V(q["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);if(!seat){var c=g.AddComponent<BoxCollider>();c.size=V(q["size"]);c.center=V(q["center"]);var rr=g.GetComponentsInChildren<MeshRenderer>();var lod=g.GetComponent<LODGroup>()??g.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.12f,rr.Where(r=>r.name.EndsWith("LOD0")).Cast<Renderer>().ToArray()),new LOD(.006f,rr.Where(r=>r.name.EndsWith("LOD1")).Cast<Renderer>().ToArray())});lod.RecalculateBounds();}foreach(var t in g.GetComponentsInChildren<Transform>(true))GameObjectUtility.SetStaticEditorFlags(t.gameObject,StaticEditorFlags.OccludeeStatic);}
  foreach(var t in root.GetComponentsInChildren<Transform>(true))if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);foreach(var c in t.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}Physics.SyncTransforms();Undo.CollapseUndoOperations(group);EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);string json=File.ReadAllText(H+"layout.json");File.WriteAllText(R+"/SourceAssets/B1_FullFloor/layout.json",json);File.WriteAllText(R+"/Docs/도면/Decision/원형공동/B1_제작현황/as_built_layout.json",json);var result=new{seats=8,newModels=2,tableWidth=4.2,screenWidth=2.9,room="C05",totalPlacements=JObject.Parse(json)["placements"].Count()};File.WriteAllText(O+"conference_applied.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Audit(){var s=Check();var root=GameObject.Find("B1_ResearchAndStaffFloor");var p=JObject.Parse(File.ReadAllText(H+"layout.json"));var errors=new List<string>();foreach(var q in p["placements"]){var t=root.transform.Find("B1_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);if(!t){errors.Add("Missing "+q["name"]);continue;}if(Vector3.Distance(t.localPosition,V(q["position"]))>.002f)errors.Add("Position "+t.name);if(Quaternion.Angle(t.localRotation,Quaternion.Euler(0,(float)q["yaw"],0))>.01f)errors.Add("Rotation "+t.name);}
  var fs=root.GetComponentsInChildren<MeshFilter>(true);var rs=root.GetComponentsInChildren<Renderer>(true);foreach(var f in fs)if(!f.sharedMesh)errors.Add("Missing mesh "+f.name);foreach(var r in rs)if(r.sharedMaterials.Any(m=>!m))errors.Add("Missing material "+r.name);var forbidden=new[]{"TrialTarget","PredictiveSensor","TrialControl","AcquisitionRack","SynchronizationCart","SensorStorage","ElectrodePrep","SignalAnalysis","SensorPrep","ExperimentCartridges","ObservationConsole","CentrifugeBench","SampleTrolley"};var bad=root.GetComponentsInChildren<Transform>(true).Where(t=>forbidden.Any(f=>t.name.Contains(f))).Select(t=>t.name).ToArray();if(bad.Length>0)errors.AddRange(bad);var result=new{scene=s.path,saved=!s.isDirty,placements=p["placements"].Count(),forbiddenObjects=bad,missingScripts=root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),errors,renderers=rs.Length,lodGroups=root.GetComponentsInChildren<LODGroup>(true).Length,lights=root.GetComponentsInChildren<Light>(true).Count(l=>l.enabled),subjectBoundary="B4 -> B3",newRuntimeScripts=false};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
 public static object Close(){var s=Check();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);Selection.activeGameObject=GameObject.Find("B1_C05_Sector");var v=SceneView.lastActiveSceneView;if(v){v.sceneLighting=true;v.LookAt(new Vector3(22,-16.4f,21),Quaternion.Euler(4,0,0),4,false,true);v.Focus();v.Repaint();}var result=new{saved=!s.isDirty,playing=Application.isPlaying,scene=s.path,selection=Selection.activeGameObject.name,mouseEnabled=UnityEngine.InputSystem.Mouse.current.enabled,keyboardEnabled=UnityEngine.InputSystem.Keyboard.current.enabled,occlusionRunning=StaticOcclusionCulling.isRunning};File.WriteAllText(O+"final_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
